  'translate.settings.tagSuperFast': "Cực nhanh",
  'translate.settings.tagKoharuGguf': "Koharu GGUF",
  'translate.settings.descQwen7b': "Cân bằng hoàn hảo: dịch thoát ý, chuẩn ngữ cảnh Manga/Manhwa từ Nhật, Trung, Hàn sang Việt.",
  'translate.settings.descQwen15b': "Nhẹ và nhanh, phù hợp máy tính cấu hình văn phòng hoặc laptop không có card đồ họa rời.",
  'translate.settings.descQwen14b': "Văn phong xuất sắc cho cốt truyện phức tạp, tiểu thuyết. Đòi hỏi card đồ họa rời mạnh.",
  'translate.settings.descGemma412b': "Bản tinh chỉnh GGUF chuẩn Koharu, tối ưu ngữ cảnh hội thoại Manga chuyên sâu.",
  'translate.settings.descGemma27b': "Mô hình từ Google, khả năng hành văn tự nhiên và đa ngôn ngữ tốt.",
  'translate.settings.descLlama323b': "Mô hình gọn nhẹ từ Meta, phản hồi hội thoại ngắn siêu tốc.",
  'translate.settings.langAuto': "Tự động nhận diện (Khuyên dùng)",
  'translate.settings.langJa': "Tiếng Nhật",
  'translate.settings.langZh': "Tiếng Trung",
  'translate.settings.langKo': "Tiếng Hàn",
  'translate.settings.langEn': "Tiếng Anh",
  'translate.settings.langVi': "Tiếng Việt",
  'translate.settings.guideOllamaDesc': "Cung cấp API để chạy mô hình AI dịch thuật...",
  'translate.settings.guideEndpointDefault': "Endpoint mặc định: {url}",
  'translate.settings.guideFaq1Q': "App báo lỗi \"Kiểm tra kết nối thất bại\"?",
  'translate.settings.guideFaq1A': "Hãy đảm bảo bạn đã mở ứng dụng Ollama (hoặc chạy lệnh `ollama serve`). Kiểm tra xem port 11434 (Ollama) có bị tường lửa chặn không.",
  'translate.settings.guideFaq2Q': "Dịch truyện bị giật lag, đơ máy?",
  'translate.settings.guideFaq2A': "Model 7B hoặc 14B có thể quá nặng nếu máy tính không có card đồ họa rời (VRAM). Hãy đổi sang model nhẹ hơn như Qwen 2.5 1.5B hoặc dùng Cloud (Gemini - miễn phí).",
  'translate.settings.guideFaq3Q': "Cài đặt sai lung tung làm sao khôi phục?",
  'translate.settings.guideFaq3A': "Hãy bấm vào nút \"Khôi phục mặc định\" (biểu tượng mũi tên tròn) ở góc trên bên phải để đưa mọi thứ về trạng thái tối ưu ban đầu.",
  'translate.settings.guideFaq4Q': "Người dùng mới cần tải những model nào để chạy được?",
  'translate.settings.guideFaq4A': "Bạn cần cài đặt đủ 3 mô hình ONNX offline trong mục MODELS (AI):\n• (1) Comic Text Detector (~168MB): Bóc tách khung thoại và vùng chữ manga.\n• (2) Manga OCR (~117MB): Nhận diện chữ tiếng Nhật (Kanji, Kana, Furigana).\n• (3) LaMa Inpainting (~208MB): Tẩy sạch chữ gốc và phục hồi nét vẽ tranh.\n• Model dịch (LLM): Dùng Google Gemini (miễn phí, không cần tải) hoặc Ollama (qwen2.5:7b để dịch offline 100%).\n• Cách cài đặt: Mở Cài đặt → cuộn xuống MODELS (AI) rồi bấm Tải về (hoặc Import file .onnx nếu có sẵn).",
  'translate.settings.guideModelsTab': "Model AI",
  'translate.settings.guideRecommendation': "Khuyên dùng: Google Gemini (miễn phí, nhanh) hoặc Ollama Qwen 2.5 7B (dịch hay nhất trên máy).",
